insert into public.collection_entries(set_id,item_type_id) select 'apple-essentials',id from public.item_types where slug in('iphone-13-128','iphone-14-pro','macbook-air-m2','apple-watch-se-used','ipad-air-5') on conflict do nothing;
insert into public.collection_entries(set_id,item_type_id) select 'retro-gaming',id from public.item_types where slug in('game-boy-color','game-boy-original-used','nintendo-gamecube','nintendo-wii','xbox-360','psp-3000') on conflict do nothing;
insert into public.collection_entries(set_id,item_type_id) select 'sneaker-rotation',id from public.item_types where slug in('air-jordan-1-high','dunk-low-panda','adidas-samba','yeezy-boost-350','new-balance-2002r') on conflict do nothing;
alter table public.collection_sets enable row level security; alter table public.collection_entries enable row level security; revoke all on public.collection_sets,public.collection_entries from anon,authenticated;

create table if not exists public.market_highlights(highlight_date date primary key,trade_id uuid not null references public.trades(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,item_id uuid not null references public.inventory_items(id) on delete cascade,profit numeric(12,2) not null,profit_pct numeric(8,2) not null,updated_at timestamptz not null default now());
alter table public.market_highlights enable row level security; revoke all on public.market_highlights from anon,authenticated;

create or replace function public.after_trade_progression() returns trigger language plpgsql security definer set search_path=public as $$
declare old_cost numeric; margin numeric; sec uuid; ch public.flip_chains%rowtype; existing_pct numeric; item_type uuid; sell_secs numeric;
begin
 old_cost:=new.amount-new.fee-coalesce(new.seller_profit,0); margin:=case when old_cost>0 then round(100*coalesce(new.seller_profit,0)/old_cost,2) else 0 end; select item_type_id into item_type from public.inventory_items where id=new.item_id;
 insert into public.goal_events(profile_id,event_type,value,meta,created_at) values(new.buyer_id,'purchase',1,jsonb_build_object('amount',new.amount),new.completed_at),(new.seller_id,'sale',1,jsonb_build_object('profit',new.seller_profit,'margin_pct',margin),new.completed_at);
 select extract(epoch from(new.completed_at-l.created_at)) into sell_secs from public.listings l where l.id=new.listing_id; if sell_secs is not null and sell_secs<=1800 then insert into public.goal_events(profile_id,event_type,value,meta,created_at) values(new.seller_id,'fast_sale',1,jsonb_build_object('seconds',sell_secs),new.completed_at); end if;
 if exists(select 1 from public.offers where listing_id=new.listing_id and status='accepted') then insert into public.goal_events(profile_id,event_type,value,meta,created_at) values(new.buyer_id,'negotiated_trade',1,'{}',new.completed_at),(new.seller_id,'negotiated_trade',1,'{}',new.completed_at); end if;
 select id into sec from public.seasons where is_active and new.completed_at>=starts_at and new.completed_at<ends_at order by starts_at desc limit 1; if sec is not null then insert into public.profile_season_stats(season_id,profile_id,volume,purchases,unique_item_types) values(sec,new.buyer_id,new.amount,1,array[item_type]) on conflict(season_id,profile_id) do update set volume=profile_season_stats.volume+excluded.volume,purchases=profile_season_stats.purchases+1,unique_item_types=(select array_agg(distinct x) from unnest(profile_season_stats.unique_item_types||excluded.unique_item_types) x),updated_at=now(); insert into public.profile_season_stats(season_id,profile_id,volume,profit,sales,best_margin_pct,unique_item_types) values(sec,new.seller_id,new.amount,coalesce(new.seller_profit,0),1,greatest(margin,0),array[item_type]) on conflict(season_id,profile_id) do update set volume=profile_season_stats.volume+excluded.volume,profit=profile_season_stats.profit+excluded.profit,sales=profile_season_stats.sales+1,best_margin_pct=greatest(profile_season_stats.best_margin_pct,excluded.best_margin_pct),unique_item_types=(select array_agg(distinct x) from unnest(profile_season_stats.unique_item_types||excluded.unique_item_types) x),updated_at=now(); end if;
 select * into ch from public.flip_chains where profile_id=new.seller_id and is_active order by updated_at desc limit 1 for update; if not found or ch.current_capital<old_cost then if found then update public.flip_chains set is_active=false where id=ch.id; end if; insert into public.flip_chains(profile_id,start_capital,current_capital,trade_count,total_profit) values(new.seller_id,old_cost,new.amount,1,coalesce(new.seller_profit,0)) returning * into ch; else update public.flip_chains set current_capital=new.amount,trade_count=trade_count+1,total_profit=total_profit+coalesce(new.seller_profit,0),updated_at=now() where id=ch.id returning * into ch; end if; insert into public.flip_chain_steps(chain_id,trade_id,buy_price,sell_price,profit,created_at) values(ch.id,new.id,old_cost,new.amount,coalesce(new.seller_profit,0),new.completed_at) on conflict(trade_id) do nothing;
 select profit_pct into existing_pct from public.market_highlights where highlight_date=new.completed_at::date; if coalesce(new.seller_profit,0)>0 and (existing_pct is null or margin>existing_pct) then insert into public.market_highlights(highlight_date,trade_id,profile_id,item_id,profit,profit_pct,updated_at) values(new.completed_at::date,new.id,new.seller_id,new.item_id,new.seller_profit,margin,now()) on conflict(highlight_date) do update set trade_id=excluded.trade_id,profile_id=excluded.profile_id,item_id=excluded.item_id,profit=excluded.profit,profit_pct=excluded.profit_pct,updated_at=now() where excluded.profit_pct>market_highlights.profit_pct; if margin>=10 and (existing_pct is null or margin>=existing_pct+5) then insert into public.tradeup_announcements(body,is_active) values('Новый рекорд дня: сделка с маржой +'||trim(to_char(margin,'FM999990.0'))||'%. Рынок TradeUP написал эту историю сам.',true); end if; end if;
 return new;
end $$;
drop trigger if exists trades_progression on public.trades; create trigger trades_progression after insert on public.trades for each row execute function public.after_trade_progression();

create or replace function public.claim_daily_goal_atomic(p_profile_id uuid,p_goal_key text) returns integer language plpgsql security definer set search_path=public as $$ declare complete boolean:=false; reward integer:=0; begin
 if p_goal_key='first_sale' then select exists(select 1 from public.goal_events where profile_id=p_profile_id and event_type='sale' and created_at::date=current_date) into complete; reward:=80;
 elsif p_goal_key='margin_8' then select exists(select 1 from public.goal_events where profile_id=p_profile_id and event_type='sale' and created_at::date=current_date and coalesce((meta->>'margin_pct')::numeric,0)>=8) into complete; reward:=120;
 elsif p_goal_key='fast_sale' then select exists(select 1 from public.goal_events where profile_id=p_profile_id and event_type='fast_sale' and created_at::date=current_date) into complete; reward:=100;
 elsif p_goal_key='negotiate' then select exists(select 1 from public.goal_events where profile_id=p_profile_id and event_type='negotiated_trade' and created_at::date=current_date) into complete; reward:=90; else raise exception 'goal_not_found'; end if;
 if not complete then raise exception 'goal_not_complete'; end if; insert into public.goal_claims(profile_id,goal_key,goal_date,xp_awarded) values(p_profile_id,p_goal_key,current_date,reward) on conflict do nothing; if not found then raise exception 'goal_already_claimed'; end if; insert into public.profile_progress(profile_id,xp,level,updated_at) values(p_profile_id,reward,1+floor(reward/500.0)::int,now()) on conflict(profile_id) do update set xp=profile_progress.xp+reward,level=1+floor((profile_progress.xp+reward)/500.0)::int,updated_at=now(); return reward; end $$;

revoke all on function public.create_auction_atomic(uuid,uuid,text,numeric,integer) from public,anon,authenticated; grant execute on function public.create_auction_atomic(uuid,uuid,text,numeric,integer) to service_role;
revoke all on function public.place_auction_bid_atomic(uuid,uuid,numeric) from public,anon,authenticated; grant execute on function public.place_auction_bid_atomic(uuid,uuid,numeric) to service_role;
revoke all on function public.settle_auction_atomic(uuid) from public,anon,authenticated; grant execute on function public.settle_auction_atomic(uuid) to service_role;
revoke all on function public.settle_due_auctions(integer) from public,anon,authenticated; grant execute on function public.settle_due_auctions(integer) to service_role;
revoke all on function public.create_bundle_atomic(uuid,uuid[],text,text,numeric) from public,anon,authenticated; grant execute on function public.create_bundle_atomic(uuid,uuid[],text,text,numeric) to service_role;
revoke all on function public.cancel_bundle_atomic(uuid,uuid) from public,anon,authenticated; grant execute on function public.cancel_bundle_atomic(uuid,uuid) to service_role;
revoke all on function public.buy_bundle_atomic(uuid,uuid) from public,anon,authenticated; grant execute on function public.buy_bundle_atomic(uuid,uuid) to service_role;
revoke all on function public.claim_daily_goal_atomic(uuid,text) from public,anon,authenticated; grant execute on function public.claim_daily_goal_atomic(uuid,text) to service_role;
revoke all on function public.after_trade_progression() from public,anon,authenticated;
